                            <line x1=\"358\" y1=\"125\" x2=\"372\" y2=\"70\" stroke=\"#4B6EFB\" opacity=\"0.5\"></line>

                            <line x1=\"358\" y1=\"50\" x2=\"372\" y2=\"100\" stroke=\"#4B6EFB\" opacity=\"0.5\"></line>
