                            <rect x=\"70\" y=\"120\" width=\"70\" height=\"25\" fill=\"#FFF\" stroke=\"#333\" rx=\"3\"></rect>
                            <text x=\"75\" y=\"135\" font-family=\"Arial\" font-size=\"8\" fill=\"#333\">Client Report</text>
                            <circle cx=\"65\" cy=\"132\" r=\"5\" fill=\"#4BFB9D\" opacity=\"0.7\"></circle>
