                            <circle cx=\"65\" cy=\"162\" r=\"5\" fill=\"#4BFB9D\" opacity=\"0.7\"></circle>
                            <text x=\"63\" y=\"165\" font-family=\"Arial\" font-weight=\"bold\" font-size=\"10\" fill=\"#FFF\">✓</text>
                            
                            <!-- Spam Emails -->
                            <rect x=\"260\" y=\"90\" width=\"70\" height=\"25\" fill=\"#FFF\" stroke=\"#333\" rx=\"3\"></rect>
