                            <circle cx=\"255\" cy=\"132\" r=\"5\" fill=\"#FB4B4B\" opacity=\"0.7\"></circle>
                            <text x=\"253\" y=\"135\" font-family=\"Arial\" font-weight=\"bold\" font-size=\"10\" fill=\"#FFF\">✗</text>
                            
                            <rect x=\"260\" y=\"150\" width=\"70\" height=\"25\" fill=\"#FFF\" stroke=\"#333\" rx=\"3\"></rect>
                            <text x=\"265\" y=\"165\" font-family=\"Arial\" font-size=\"8\" fill=\"#333\">Urgent: Help!</text>
                            <circle cx=\"255\" cy=\"162\" r=\"5\" fill=\"#FB4B4B\" opacity=\"0.7\"></circle>
                            <text x=\"253\" y=\"165\" font-family=\"Arial\" font-weight=\"bold\" font-size=\"10\" fill=\"#FFF\">✗</text>
                            
                            <!-- Classification Engine -->
                            <rect x=\"160\" y=\"110\" width=\"80\" height=\"40\" fill=\"#4B6EFB\" opacity=\"0.2\" stroke=\"#4B6EFB\" rx=\"5\"></rect>
                            <text x=\"170\" y=\"130\" font-family=\"Arial\" font-weight=\"bold\" font-size=\"10\" fill=\"#333\">Classification</text>
                            <text x=\"185\" y=\"140\" font-family=\"Arial\" font-size=\"8\" fill=\"#333\">Algorithm</text>
                            
                            <!-- Sherlock Holmes -->
                            <circle cx=\"200\" cy=\"80\" r=\"10\" fill=\"#333\"></circle>
                            <path d=\"M195 75 C195 70, 205 70, 205 75\" fill=\"none\" stroke=\"#333\"></path>
