                            <text x=\"55\" y=\"163\" font-family=\"Arial\" font-size=\"7\" fill=\"#333\">FOR</text>
                            <text x=\"55\" y=\"170\" font-family=\"Arial\" font-size=\"7\" fill=\"#333\">SALE</text>
                            <rect x=\"50\" y=\"145\" width=\"25\" height=\"5\" fill=\"#FB4B4B\" opacity=\"0.7\"></rect>
                            
                            <!-- Price Tag -->
