                            <rect x=\"150\" y=\"60\" width=\"30\" height=\"30\" fill=\"#FFF\" stroke=\"#333\"></rect>
                            <text x=\"155\" y=\"80\" font-family=\"Arial\" font-size=\"12\" fill=\"#333\">AI</text>
                            
