                            <path d=\"M180 75 C220 75, 280 100, 320 150\" fill=\"none\" stroke=\"#4B6EFB\" stroke-dasharray=\"2,2\"></path>
                            <path d=\"M330 215 L350 215\" fill=\"none\" stroke=\"#333\"></path>
                            <polygon points=\"350,215 345,212 345,218\" fill=\"#333\"></polygon>
                            
                            <!-- Production Stats -->
                            <rect x=\"70\" y=\"200\" width=\"260\" height=\"30\" fill=\"#FFF\" stroke=\"#333\" rx=\"5\"></rect>
