                            <path d=\"M215 170 C225 155, 235 140, 245 130\" fill=\"none\" stroke=\"#4B6EFB\" stroke-width=\"1\" stroke-dasharray=\"2,2\"></path>
                            
                            <!-- Future Text -->
                            <text x=\"200\" y=\"210\" font-family=\"Arial\" font-weight=\"bold\" font-size=\"12\" fill=\"#333\" text-anchor=\"middle\">Future Generative AI Landscape</text>
