                            <circle cx=\"160\" cy=\"90\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            <circle cx=\"190\" cy=\"80\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            <circle cx=\"220\" cy=\"90\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            <circle cx=\"150\" cy=\"110\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            <circle cx=\"180\" cy=\"115\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
