                            <circle cx=\"240\" cy=\"115\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            <circle cx=\"160\" cy=\"140\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            <circle cx=\"190\" cy=\"140\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            <circle cx=\"220\" cy=\"135\" r=\"6\" fill=\"#4B6EFB\" opacity=\"0.7\"></circle>
                            
                            <!-- Neural Connections -->
                            <line x1=\"160\" y1=\"90\" x2=\"190\" y2=\"80\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"190\" y1=\"80\" x2=\"220\" y2=\"90\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"160\" y1=\"90\" x2=\"150\" y2=\"110\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"190\" y1=\"80\" x2=\"180\" y2=\"115\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"220\" y1=\"90\" x2=\"210\" y2=\"110\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"220\" y1=\"90\" x2=\"240\" y2=\"115\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"150\" y1=\"110\" x2=\"160\" y2=\"140\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"180\" y1=\"115\" x2=\"190\" y2=\"140\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"210\" y1=\"110\" x2=\"220\" y2=\"135\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"240\" y1=\"115\" x2=\"220\" y2=\"135\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"150\" y1=\"110\" x2=\"180\" y2=\"115\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"180\" y1=\"115\" x2=\"210\" y2=\"110\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
                            <line x1=\"210\" y1=\"110\" x2=\"240\" y2=\"115\" stroke=\"#4B6EFB\" stroke-width=\"1\"></line>
