-- Table: project_submissions
DROP TABLE IF EXISTS `project_submissions`;
CREATE TABLE `project_submissions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `project_id` int NOT NULL,
  `submission_text` text COLLATE utf8mb4_unicode_ci,
  `submission_file_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uploaded_file_id` int DEFAULT NULL,
  `status` enum('submitted','graded','returned') COLLATE utf8mb4_unicode_ci DEFAULT 'submitted',
  `score` decimal(5,2) DEFAULT NULL,
  `feedback` text COLLATE utf8mb4_unicode_ci,
  `graded_by` int DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `graded_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `graded_by` (`graded_by`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_status` (`status`),
  KEY `idx_uploaded_file_id` (`uploaded_file_id`),
  KEY `idx_graded_at` (`graded_at`),
  CONSTRAINT `fk_project_submissions_uploaded_file` FOREIGN KEY (`uploaded_file_id`) REFERENCES `uploaded_files` (`id`) ON DELETE SET NULL,
  CONSTRAINT `project_submissions_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `project_submissions_ibfk_2` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `project_submissions_ibfk_3` FOREIGN KEY (`graded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: projects
DROP TABLE IF EXISTS `projects`;
CREATE TABLE `projects` (
  `id` int NOT NULL AUTO_INCREMENT,
  `course_id` int NOT NULL,
  `module_id` int NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `order` int DEFAULT '0',
  `description` text COLLATE utf8mb4_unicode_ci,
  `instructions` text COLLATE utf8mb4_unicode_ci,
  `requirements` text COLLATE utf8mb4_unicode_ci,
  `max_score` int DEFAULT '100',
  `due_date` date DEFAULT NULL,
  `is_published` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_project_slug_per_course` (`course_id`,`slug`),
  KEY `idx_module_id` (`module_id`),
  KEY `idx_is_published` (`is_published`),
  KEY `idx_course_id` (`course_id`),
  KEY `idx_course_order` (`course_id`,`order`),
  CONSTRAINT `fk_projects_course_id` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `projects_ibfk_1` FOREIGN KEY (`module_id`) REFERENCES `modules` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for table: projects
INSERT INTO `projects` (`id`, `course_id`, `module_id`, `title`, `slug`, `order`, `description`, `instructions`, `requirements`, `max_score`, `due_date`, `is_published`, `created_at`, `updated_at`) VALUES ('1', '1', '1', 'AI Concept Map Project', 'ai-concept-map-project-1', '1', 'Create a comprehensive concept map that illustrates your understanding of fundamental AI concepts and their relationships.', 'Create a visual concept map that includes: AI definition, machine learning, types of learning (supervised, unsupervised, reinforcement), neural networks, and how they interconnect. Use any digital tool (Draw.io, Lucidchart, PowerPoint, etc.) or hand-draw and photograph your map.', '- Include at least 15 key AI concepts
- Show clear relationships between concepts with labeled arrows
- Use color coding to group related concepts
- Include a legend explaining your color scheme
- Submit as PDF or image file (PNG/JPG)
- Include a 200-word written explanation of your map', '100', NULL, '1', '2025-11-18 11:34:17', '2025-12-30 19:32:35');
INSERT INTO `projects` (`id`, `course_id`, `module_id`, `title`, `slug`, `order`, `description`, `instructions`, `requirements`, `max_score`, `due_date`, `is_published`, `created_at`, `updated_at`) VALUES ('2', '1', '2', 'Generative AI Application Showcase', 'generative-ai-application-showcase-2', '2', 'Explore and document your experience using generative AI tools for a practical task.', 'Choose one generative AI tool (ChatGPT, DALL-E, Midjourney, etc.) and complete a creative project. Document your process, prompts used, iterations, and final results. Reflect on the AI\'s capabilities and limitations.', '- Select and introduce your chosen AI tool
- Define your creative goal/task
- Document at least 5 different prompts you used
- Show iterations and refinements
- Present final outputs (images, text, or other)
- Write a 500-word reflection on the experience
- Discuss ethical considerations
- Submit as PDF with embedded media', '100', NULL, '1', '2025-11-18 11:34:17', '2025-12-30 19:32:35');
INSERT INTO `projects` (`id`, `course_id`, `module_id`, `title`, `slug`, `order`, `description`, `instructions`, `requirements`, `max_score`, `due_date`, `is_published`, `created_at`, `updated_at`) VALUES ('3', '1', '3', 'Advanced Search Strategy Report', 'advanced-search-strategy-report-3', '3', 'Demonstrate mastery of advanced search techniques by solving a complex information challenge.', 'You are a researcher investigating \"The impact of AI on employment in your country.\" Use advanced search operators, Boolean logic, and AI-powered search tools to find credible sources. Document your search strategy and findings.', '- Define your research question clearly
- Document 10 different search queries using:
  * Boolean operators (AND, OR, NOT)
  * Search operators (site:, filetype:, intitle:, etc.)
  * Date range filtering
- Use at least 3 different search engines/tools
- Evaluate source credibility for each result
- Create an annotated bibliography (10 sources minimum)
- Submit as PDF (1500-2000 words)', '100', NULL, '1', '2025-11-18 11:34:17', '2025-12-30 19:32:35');
INSERT INTO `projects` (`id`, `course_id`, `module_id`, `title`, `slug`, `order`, `description`, `instructions`, `requirements`, `max_score`, `due_date`, `is_published`, `created_at`, `updated_at`) VALUES ('4', '1', '4', 'AI Ethics Case Study Analysis', 'ai-ethics-case-study-analysis-4', '4', 'Analyze a real-world AI ethics scenario and propose responsible solutions.', 'Choose a documented case of AI bias, privacy violation, or ethical concern (e.g., facial recognition bias, hiring algorithm discrimination, deepfakes). Analyze the case through multiple ethical frameworks and propose improvements.', '- Describe the case (who, what, when, where)
- Identify ethical issues and stakeholders affected
- Analyze using at least 2 ethical frameworks:
  * Utilitarian approach
  * Rights-based approach
  * Fairness/justice approach
- Propose 5 concrete recommendations for improvement
- Include citations (minimum 5 credible sources)
- Address potential trade-offs and challenges
- Submit as PDF (2000-2500 words)', '100', NULL, '1', '2025-11-18 11:34:17', '2025-12-30 19:32:35');
INSERT INTO `projects` (`id`, `course_id`, `module_id`, `title`, `slug`, `order`, `description`, `instructions`, `requirements`, `max_score`, `due_date`, `is_published`, `created_at`, `updated_at`) VALUES ('5', '1', '5', 'Microsoft Copilot Productivity Challenge', 'microsoft-copilot-productivity-challenge-5', '5', 'Demonstrate proficiency with Microsoft Copilot across multiple Microsoft 365 applications.', 'Complete a series of practical tasks using Microsoft Copilot in Word, Excel, PowerPoint, and Outlook. Document your prompts, outputs, and productivity gains.', 'Complete ALL of the following tasks:
1. WORD: Create a 3-page business report using Copilot
2. EXCEL: Analyze a dataset and create visualizations with Copilot
3. POWERPOINT: Generate a 10-slide presentation with Copilot
4. OUTLOOK: Draft 3 professional emails using Copilot

For each task:
- Screenshot your Copilot prompts
- Show the generated output
- Describe any edits/refinements you made
- Estimate time saved vs. manual work

Submit as ZIP file containing:
- All created documents
- Screenshots of prompts
- 1000-word reflection on Copilot\'s strengths/limitations', '100', NULL, '1', '2025-11-18 11:34:17', '2025-12-30 19:32:35');
INSERT INTO `projects` (`id`, `course_id`, `module_id`, `title`, `slug`, `order`, `description`, `instructions`, `requirements`, `max_score`, `due_date`, `is_published`, `created_at`, `updated_at`) VALUES ('6', '1', '6', 'AI Future Scenario Planning', 'ai-future-scenario-planning-6', '6', 'Develop a detailed scenario exploring AI\'s potential impact on society in the next 10 years.', 'Create a comprehensive scenario narrative exploring how AI might transform a specific sector (healthcare, education, transportation, etc.) by 2035. Include both opportunities and challenges.', '- Choose a specific sector to focus on
- Research current AI trends in that sector
- Develop a detailed 10-year scenario including:
  * Timeline of key developments (2025-2035)
  * Major AI technologies deployed
  * Changes to jobs and skills needed
  * Societal benefits and risks
  * Ethical considerations
  * Regulatory needs
- Include data visualizations (timeline, charts, infographics)
- Provide 10 credible sources
- Submit as PDF (2500-3000 words) with visuals', '100', NULL, '1', '2025-11-18 11:34:17', '2025-12-30 19:32:35');

-- Table: quiz_attempt_answers
DROP TABLE IF EXISTS `quiz_attempt_answers`;
CREATE TABLE `quiz_attempt_answers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `attempt_id` int NOT NULL,
  `question_id` int NOT NULL,
  `question_text` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Snapshot of question at time of attempt',
  `user_answer` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Student answer (could be text, multiple choice index, etc)',
  `correct_answer` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Correct answer at time of attempt',
  `is_correct` tinyint(1) NOT NULL DEFAULT '0',
  `points_awarded` decimal(5,2) NOT NULL DEFAULT '0.00',
  `points_possible` decimal(5,2) NOT NULL DEFAULT '1.00',
  `time_spent_seconds` int DEFAULT NULL COMMENT 'Time spent on this question',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_attempt_answers` (`attempt_id`),
  KEY `idx_question_performance` (`question_id`,`is_correct`),
  CONSTRAINT `quiz_attempt_answers_ibfk_1` FOREIGN KEY (`attempt_id`) REFERENCES `quiz_attempts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

