-- Table: quiz_questions
DROP TABLE IF EXISTS `quiz_questions`;
CREATE TABLE `quiz_questions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `quiz_id` int NOT NULL,
  `question_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` json NOT NULL,
  `correct_option` int NOT NULL,
  `explanation` text COLLATE utf8mb4_unicode_ci,
  `points` int DEFAULT '1',
  `order_index` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_quiz_id` (`quiz_id`),
  KEY `idx_order` (`quiz_id`,`order_index`),
  CONSTRAINT `quiz_questions_ibfk_1` FOREIGN KEY (`quiz_id`) REFERENCES `quizzes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_correct_option` CHECK (((`correct_option` >= 0) and (`correct_option` <= 10)))
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for table: quiz_questions
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('1', '1', 'What is artificial intelligence (AI)?', '[\"A computer program that can only perform predetermined tasks\", \"The ability of a computer system to learn from past data and errors, enabling it to make increasingly accurate predictions\", \"A robot with human-like characteristics\", \"Software that allows computers to connect to the internet\"]', '1', 'AI is the ability of a computer system to learn from past data and errors, enabling it to make increasingly accurate predictions for future behavior.', '1', '1', '2025-11-04 14:58:16', '2025-11-04 14:58:16');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('2', '1', 'What is the relationship between AI and machine learning?', '[\"They are completely different technologies with no relation\", \"AI and machine learning are exactly the same thing\", \"Machine learning is a subset of AI\", \"AI is a subset of machine learning\"]', '2', 'Machine learning is a subset of artificial intelligence. All machine learning is AI, but not all AI involves machine learning.', '1', '2', '2025-11-04 14:58:16', '2025-11-04 14:58:16');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('3', '1', 'What are patterns in data?', '[\"Random occurrences with no significance\", \"Identifiable repetitive behaviors or structures in data\", \"Mistakes in data collection\", \"Visualization tools for data presentation\"]', '1', 'Patterns are identifiable repetitive behaviors or structures that occur within data. AI models are particularly good at recognizing these patterns.', '1', '3', '2025-11-04 14:58:16', '2025-11-04 14:58:16');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('4', '1', 'What is supervised learning?', '[\"Learning that requires a human supervisor present at all times\", \"Learning that happens without any data labels or guidance\", \"An algorithm trained on labeled data with correct outputs\", \"Learning that occurs by trial and error with rewards and penalties\"]', '2', 'In supervised learning, the algorithm is trained on labeled data, where inputs are paired with correct outputs, allowing it to learn the relationship between them.', '1', '4', '2025-11-04 14:58:16', '2025-11-04 14:58:16');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('5', '2', 'What is deep learning?', '[\"Learning that happens deep under water\", \"A subfield of machine learning inspired by the structure and function of the brain\", \"Learning that requires deep concentration\", \"A type of learning that only works with very large datasets\"]', '1', 'Deep learning is a subfield of machine learning concerned with algorithms inspired by the structure and function of the brain called artificial neural networks.', '1', '5', '2025-11-04 14:58:16', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('6', '2', 'What is Natural Language Processing (NLP)?', '[\"A programming language used to create AI applications\", \"The ability of computers to understand and speak natural human languages\", \"An application of AI which enables machines to process and comprehend human language\", \"A system that translates computer code into human language\"]', '2', 'Natural Language Processing (NLP) is an application of AI which enables machines to both process and comprehend human language in the way it is written.', '1', '6', '2025-11-04 14:58:16', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('7', '2', 'What is a classification algorithm used for?', '[\"Organizing files on a computer\", \"Sorting items into categories based on learned patterns\", \"Creating classifications for new types of data\", \"Ranking items by importance\"]', '1', 'Classification algorithms are used for sorting items into categories based on learned patterns, such as distinguishing spam from legitimate emails.', '1', '7', '2025-11-04 14:58:16', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('8', '2', 'What is reinforcement learning?', '[\"Learning that involves positive reinforcement only\", \"Learning through online courses and tutorials\", \"An algorithm trained by interacting with its environment to achieve a goal, receiving rewards or penalties\", \"Learning that reinforces existing knowledge without adding new information\"]', '2', 'Reinforcement learning is where an algorithm learns by interacting with its environment, taking actions to maximize rewards and minimize penalties, similar to how we learn from experience.', '1', '8', '2025-11-04 14:58:16', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('9', '3', 'What is the Internet of Things (IoT)?', '[\"A network of internet websites\", \"A vast network of interconnected physical devices that collect and share data\", \"A special internet connection for smart devices\", \"The underlying structure of the internet\"]', '1', 'The Internet of Things (IoT) is a vast network of interconnected physical devices, ranging from everyday household items to wearable devices, that collect and share data via the internet.', '1', '9', '2025-11-04 14:58:16', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('10', '3', 'How do AI algorithms like regression differ from classification algorithms?', '[\"Regression algorithms are older than classification algorithms\", \"Classification algorithms sort data into categories while regression algorithms predict continuous values\", \"Regression algorithms are simpler and less accurate\", \"Classification algorithms require more data to function properly\"]', '1', 'While classification algorithms sort data into discrete categories (like spam/not spam), regression algorithms predict continuous numerical values, such as prices or temperatures.', '1', '10', '2025-11-04 14:58:16', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('11', '3', 'What is artificial intelligence (AI)?', '[\"A computer program that can only perform predetermined tasks\", \"The ability of a computer system to learn from past data and errors, enabling it to make increasingly accurate predictions\", \"A robot with human-like characteristics\", \"Software that allows computers to connect to the internet\"]', '1', 'AI is the ability of a computer system to learn from past data and errors, enabling it to make increasingly accurate predictions for future behavior.', '1', '1', '2025-11-12 12:19:48', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('12', '4', 'What is the relationship between AI and machine learning?', '[\"They are completely different technologies with no relation\", \"AI and machine learning are exactly the same thing\", \"Machine learning is a subset of AI\", \"AI is a subset of machine learning\"]', '2', 'Machine learning is a subset of artificial intelligence. All machine learning is AI, but not all AI involves machine learning.', '1', '2', '2025-11-12 12:19:48', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('13', '4', 'What are patterns in data?', '[\"Random occurrences with no significance\", \"Identifiable repetitive behaviors or structures in data\", \"Mistakes in data collection\", \"Visualization tools for data presentation\"]', '1', 'Patterns are identifiable repetitive behaviors or structures that occur within data. AI models are particularly good at recognizing these patterns.', '1', '3', '2025-11-12 12:19:48', '2025-11-18 11:27:42');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('14', '4', 'What is supervised learning?', '[\"Learning that requires a human supervisor present at all times\", \"Learning that happens without any data labels or guidance\", \"An algorithm trained on labeled data with correct outputs\", \"Learning that occurs by trial and error with rewards and penalties\"]', '2', 'In supervised learning, the algorithm is trained on labeled data, where inputs are paired with correct outputs, allowing it to learn the relationship between them.', '1', '4', '2025-11-12 12:19:48', '2025-11-18 11:27:42');
