INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question_text`, `options`, `correct_option`, `explanation`, `points`, `order_index`, `created_at`, `updated_at`) VALUES ('18', '5', 'What is reinforcement learning?', '[\"Learning that involves positive reinforcement only\", \"Learning through online courses and tutorials\", \"An algorithm trained by interacting with its environment to achieve a goal, receiving rewards or penalties\", \"Learning that reinforces existing knowledge without adding new information\"]', '2', 'Reinforcement learning is where an algorithm learns by interacting with its environment, taking actions to maximize rewards and minimize penalties, similar to how we learn from experience.', '1', '8', '2025-11-12 12:19:48', '2025-11-18 11:27:42');
